mapper.select:
select a.*
from margin_base_info a,contract_base_info b

    a.contract_id = b.id
    and a.client_id = #{dto.clientId}
    and a.contract_code LIKE concat('%', #{dto.contractCode},'%')
    and a.collection_amount  >=  #{dto.amountFrom}
    and a.collection_amount  <=  #{dto.amountTo}
    and a.collection_date  >=  #{dto.collectionDateFrom}
    and a.collection_date  <=  #{dto.collectionDateTo}


order by a.create_time desc

select b.contract_id as contractId, a.record_type as recordType, sum(a.collection_amount) as amount from margin_record_info a left join margin_base_info b on a.margin_id = b.id where a.record_type in ('COLLECTION','REFUND')
and b.contract_id in
#{item}
group by a.record_type,b.contract_id;
